import { promises as fs } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(__dirname, '..');

const adapter = process.argv[2];

if (!adapter) {
  console.error('Usage: node tools/sync-chart-adapter.mjs <adapter>');
  process.exit(1);
}

const sourceDir = path.join(repoRoot, 'src', 'adapters', adapter);
const targetDir = path.join(repoRoot, 'charts', adapter, 'src');
const generatedBanner =
  '// This file is generated by tools/sync-chart-adapter.mjs.\n' +
  '// Edit the shared adapter source in src/adapters instead.\n\n';

const publicImports = new Map([
  ['../../animations/TimelinePlayback', '@risklab/charts'],
  ['../../charts/advanced/NavigatorChart', '@risklab/charts'],
  ['../../charts/advanced/RangeSelector', '@risklab/charts'],
  ['../../core/Engine', '@risklab/charts'],
  ['../../core/EventBus', '@risklab/charts'],
  ['../../core/Registry', '@risklab/charts'],
  ['../../core/SyncController', '@risklab/charts'],
  ['../../core/types', '@risklab/charts'],
  ['../../plugins/StatisticsPlugin', '@risklab/charts'],
  ['../../themes/darkTheme', '@risklab/charts'],
  ['../../themes/defaultTheme', '@risklab/charts'],
]);

await assertDirectory(sourceDir);
await fs.rm(targetDir, { recursive: true, force: true });
await copyDirectory(sourceDir, targetDir);

async function assertDirectory(dir) {
  const stat = await fs.stat(dir).catch(() => null);
  if (!stat?.isDirectory()) {
    console.error(`Adapter source directory not found: ${path.relative(repoRoot, dir)}`);
    process.exit(1);
  }
}

async function copyDirectory(fromDir, toDir) {
  await fs.mkdir(toDir, { recursive: true });
  const entries = await fs.readdir(fromDir, { withFileTypes: true });

  for (const entry of entries) {
    const fromPath = path.join(fromDir, entry.name);
    const toPath = path.join(toDir, entry.name);

    if (entry.isDirectory()) {
      await copyDirectory(fromPath, toPath);
      continue;
    }

    const raw = await fs.readFile(fromPath, 'utf8');
    const rewritten = generatedBanner + rewriteImports(raw);
    await fs.writeFile(toPath, rewritten, 'utf8');
  }
}

function rewriteImports(source) {
  let output = source.replace(/^\uFEFF/, '').replace(/\r\n/g, '\n');

  for (const [from, to] of publicImports.entries()) {
    const pattern = new RegExp(`(['"])${escapeForRegExp(from)}\\1`, 'g');
    output = output.replace(pattern, `'${to}'`);
  }

  return output;
}

function escapeForRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}
